using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class TempleMilitaryTests
{
 static WorldSession Start(){var p=NewGameWorldTests.Officer(role:StartTemplate.Daimyo,site:"site:sakai");var setup=NewGameWorldTests.Setup([p],[new(p.Id,"org:temple-test",[p.Site],false)]);var s=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,p.Id,worldArmyPolicy:NpcArmies.CompactCombatPolicy,battlefieldPolicy:BattlefieldRules.Policy,economyPolicy:RegionalDomains.Policy,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy));BattlefieldRulesTests.Good(s.DecideNewMilitary(new(new("request:temple-army"),NewMilitaryAction.Request){AuthorityPolicy=NewGameMilitary.AuthorityContract,LedgerPolicy=NewGameMilitary.LedgerIdentityContract},s.PlayerControl,s.Revision));NewGameWorldTests.At(s,s.Seconds+2);BattlefieldRulesTests.Open(s);BattlefieldRulesTests.Military(s,NewMilitaryAction.Accept);NewGameWorldTests.At(s,s.Seconds+2);BattlefieldRulesTests.Open(s);BattlefieldRulesTests.Military(s,NewMilitaryAction.Pickup);return s;}
 static void Social(WorldSession s,SocialWorldAction a){var t=SocialWorld.Temple(s.DiagnosticSnapshot(),TempleMilitary.Site);BattlefieldRulesTests.Good(s.ManageSocial(new(new("request:temple-social/"+s.Revision),a,t.Representative),s.Revision));}
 [Fact]public void AidRequiresLocalProtectionAndConsumesRealRiceOnlyOnce(){var s=Start();BattlefieldRulesTests.Good(s.ManageTempleMilitary(new(new("request:refused-aid"),TempleMilitaryAction.RequestDefense,TempleMilitary.Site),s.Revision));Assert.Null(TempleMilitary.Aid(s.DiagnosticSnapshot(),s.Seconds,s.Revision+1));Social(s,SocialWorldAction.Protect);long before=s.DiagnosticSnapshot().Communities!.Accounts.Single(a=>a.Site==TempleMilitary.Site).HouseRice;var i=new TempleMilitaryInput(new("request:temple-aid"),TempleMilitaryAction.RequestDefense,TempleMilitary.Site);BattlefieldRulesTests.Good(s.ManageTempleMilitary(i,s.Revision));Assert.Equal(ResultCode.AlreadyAccepted,s.ManageTempleMilitary(i,s.Revision).Code);Assert.Equal(before-12,s.DiagnosticSnapshot().Communities!.Accounts.Single(a=>a.Site==TempleMilitary.Site).HouseRice);var restored=new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(s.DiagnosticSnapshot())));Assert.NotNull(TempleMilitary.Aid(restored.DiagnosticSnapshot(),s.Seconds,s.Revision+1));Assert.Equal(20,TempleMilitary.Strength(restored.DiagnosticSnapshot(),s.Seconds));}
 [Fact]public void PeacefulTempleCannotBeAttackedAndKnownArmedHostilityUsesRealBattle(){var s=Start();Social(s,SocialWorldAction.Protect);BattlefieldRulesTests.Military(s,NewMilitaryAction.Load,100000);BattlefieldRulesTests.Military(s,NewMilitaryAction.Deploy);Assert.Equal(ResultCode.NotAvailable,s.ManageTempleMilitary(new(new("request:illegal-temple-attack"),TempleMilitaryAction.Attack,TempleMilitary.Site),s.Revision).Code);BattlefieldRulesTests.Military(s,NewMilitaryAction.Enter);Social(s,SocialWorldAction.BreakProtection);BattlefieldRulesTests.Good(s.ManageTempleMilitary(new(new("request:observe-temple"),TempleMilitaryAction.Observe,TempleMilitary.Site),s.Revision));BattlefieldRulesTests.Military(s,NewMilitaryAction.Deploy);BattlefieldRulesTests.Good(s.ManageTempleMilitary(new(new("request:temple-attack"),TempleMilitaryAction.Attack,TempleMilitary.Site),s.Revision));NewGameWorldTests.At(s,s.Seconds+2);Assert.True(TempleMilitary.Strength(s.DiagnosticSnapshot(),s.Seconds)<20);var restored=new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(s.DiagnosticSnapshot())));foreach(var x in new[]{s,restored})NewGameWorldTests.At(x,x.Seconds+2);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(restored.DiagnosticSnapshot()));}
}
